@using Umbraco.Cms.Web.Common.PublishedModels
@inherits UmbracoViewPage&lt;BlogFrontPage&gt;
@{
    Layout = null;
}
&lt;!DOCTYPE html&gt;
&lt;html&gt;
&lt;head&gt;
    &lt;meta charset="utf-8" /&gt;
    &lt;meta name="viewport" content="width=device-width, initial-scale=1" /&gt;
    &lt;title&gt;@Model.Value("title")&lt;/title&gt;
    &lt;script src="https://cdn.tailwindcss.com"&gt;&lt;/script&gt;
&lt;/head&gt;
&lt;body class="bg-gray-50"&gt;
    &lt;div class="min-h-screen"&gt;
        &lt;header class="bg-white shadow"&gt;
            &lt;div class="max-w-6xl mx-auto px-6 py-12"&gt;
                &lt;h1 class="text-4xl font-bold text-gray-900"&gt;@Model.Value("title")&lt;/h1&gt;
                &lt;p class="text-xl text-gray-600 mt-4"&gt;Exploring the power of Model Context Protocol&lt;/p&gt;
            &lt;/div&gt;
        &lt;/header&gt;

        &lt;main class="max-w-6xl mx-auto px-6 py-12"&gt;
            &lt;div class="grid gap-8 md:grid-cols-2"&gt;
                @foreach (var post in Model.Children&lt;BlogPost&gt;())
                {
                    &lt;article class="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition"&gt;
                        @if (post.FeaturedImage != null)
                        {
                            &lt;div class="h-64 overflow-hidden bg-gray-200"&gt;
                                &lt;img src="@post.FeaturedImage.GetCropUrl(width: 600, height: 400)" 
                                     alt="@post.Title" 
                                     class="w-full h-full object-cover" /&gt;
                            &lt;/div&gt;
                        }
                        &lt;div class="p-6"&gt;
                            &lt;h2 class="text-2xl font-bold text-gray-900 mb-3"&gt;
                                &lt;a href="@post.Url()" class="hover:text-blue-600"&gt;@post.Title&lt;/a&gt;
                            &lt;/h2&gt;
                            &lt;p class="text-gray-600 mb-4"&gt;
                                Published @post.CreateDate.ToString("MMMM d, yyyy")
                            &lt;/p&gt;
                            &lt;a href="@post.Url()" class="inline-block bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"&gt;
                                Read More
                            &lt;/a&gt;
                        &lt;/div&gt;
                    &lt;/article&gt;
                }
            &lt;/div&gt;
        &lt;/main&gt;
    &lt;/div&gt;
&lt;/body&gt;
&lt;/html&gt;

